/**
 * Where `generate:types` writes when a project sets no path, and what happens
 * to the file the old default named.
 *
 * The default file is named for Nextly. A project that left the setting out
 * may still have a `payload-types.ts` an earlier version wrote. Nextly no
 * longer rewrites it: the re-export 0.0.2-alpha.67 and alpha.68 left keeps
 * compiling and the run says it can go, and an older generated file, which
 * would augment `GeneratedTypes` a second time, is named with how to settle it.
 *
 * Driven through `runGenerateTypes` itself, with only the config loader
 * replaced, so the path the command resolves is part of what is tested.
 */
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { Command } from "commander";
import { afterEach, describe, expect, it, vi } from "vitest";

import { compile } from "../../../../../../scripts/tsc-cli.mjs";

import { DEFAULT_TYPESCRIPT_CONFIG } from "../../../shared/types/config";

const loadConfig = vi.hoisted(() => vi.fn());
vi.mock("../../utils/config-loader", () => ({ loadConfig }));

const { runGenerateTypes, registerGenerateTypesCommand } = await import(
  "../generate-types"
);
const { createContext } = await import("../../program");

const dirs: string[] = [];

afterEach(async () => {
  loadConfig.mockReset();
  await Promise.all(
    dirs.splice(0).map(dir => rm(dir, { recursive: true, force: true }))
  );
});

/** An app under src/ whose config leaves the types path at its default. */
async function appWithDefaultPath(): Promise<string> {
  const cwd = await mkdtemp(join(tmpdir(), "nextly-types-default-"));
  dirs.push(cwd);
  await mkdir(join(cwd, "src/app"), { recursive: true });
  loadConfig.mockResolvedValue({
    configPath: "nextly.config.ts",
    config: {
      collections: [],
      singles: [],
      fieldGroups: [],
      users: { fields: [{ name: "nickname", type: "text" }] },
      plugins: [],
      typescript: { ...DEFAULT_TYPESCRIPT_CONFIG },
      db: { schemasDir: "./src/db/schemas/collections" },
    },
  });
  return cwd;
}

const generatedDir = (cwd: string) => join(cwd, "src/types/generated");

/**
 * The re-export 0.0.2-alpha.67 and alpha.68 wrote in place of a generated
 * payload-types.ts, spelled out as it stands in projects on those releases.
 */
const SHIM = [
  "/**",
  " * Nextly's generated types are in nextly-types.ts. This file only",
  " * re-exports them, so imports of payload-types keep compiling; a later",
  " * release removes it. Import from nextly-types instead.",
  " */",
  'export * from "./nextly-types.js";',
  "",
].join("\n");

describe("generate:types with no types path set", () => {
  it("writes nextly-types.ts", async () => {
    const cwd = await appWithDefaultPath();

    await runGenerateTypes(
      { cwd, quiet: true, zod: false },
      createContext({ quiet: true, cwd })
    );

    const written = await readFile(
      join(generatedDir(cwd), "nextly-types.ts"),
      "utf-8"
    );
    expect(written).toContain(
      "This file was automatically generated by Nextly."
    );
  });

  it("leaves a payload-types.ts an earlier version generated as it is, and says to delete it", async () => {
    const cwd = await appWithDefaultPath();
    await mkdir(generatedDir(cwd), { recursive: true });
    const generated =
      "/* tslint:disable */\n/* eslint-disable */\n/**\n * This file was automatically generated by Nextly.\n */\n" +
      'declare module "nextly" {\n  export interface GeneratedTypes extends Config {}\n}\n';
    await writeFile(join(generatedDir(cwd), "payload-types.ts"), generated);
    const context = createContext({ quiet: true, cwd });
    const warn = vi.spyOn(context.logger, "warn");

    await runGenerateTypes({ cwd, quiet: true, zod: false }, context);

    await expect(
      readFile(join(generatedDir(cwd), "payload-types.ts"), "utf-8")
    ).resolves.toBe(generated);
    const said = warn.mock.calls.flat().join("\n");
    expect(said).toContain("payload-types.ts");
    expect(said).toMatch(/delete/i);
  });

  it("leaves the re-export an earlier release wrote, and says it can be deleted", async () => {
    const cwd = await appWithDefaultPath();
    await mkdir(generatedDir(cwd), { recursive: true });
    await writeFile(join(generatedDir(cwd), "payload-types.ts"), SHIM);
    const context = createContext({ quiet: true, cwd });
    const warn = vi.spyOn(context.logger, "warn");

    await runGenerateTypes({ cwd, quiet: true, zod: false }, context);

    await expect(
      readFile(join(generatedDir(cwd), "payload-types.ts"), "utf-8")
    ).resolves.toBe(SHIM);
    const said = warn.mock.calls.flat().join("\n");
    expect(said).toContain("payload-types.ts");
    expect(said).toMatch(/delete it/);
  });
});

/**
 * Type-checks a file importing the generated types under both names, against
 * a stand-in for the `nextly` module the generated file augments.
 *
 * Two files declaring GeneratedTypes differently fail in one of two ways. With
 * `skipLibCheck` off, tsc reports TS2320 on the declaration. With it on, as a
 * Next.js app has it, the report is skipped and whichever file the program
 * reaches first decides the type, here the old one, imported first. So the
 * file reads, through each name and through GeneratedTypes, a part only the
 * newly generated types have: `singles`, and `collections` with none in it.
 *
 * Checked by the compiler's command line, which answers the same on every
 * TypeScript version, through a config written beside the file: `paths` can
 * only be set there, and resolve from it without a `baseUrl`.
 */
async function typeErrorsImportingBothNames(
  cwd: string,
  skipLibCheck: boolean
): Promise<string[]> {
  await writeFile(
    join(cwd, "nextly-stub.d.ts"),
    "export interface GeneratedTypes {}\n"
  );
  await writeFile(
    join(cwd, "src/uses-both.ts"),
    [
      'import type { Config as Old } from "./types/generated/payload-types.js";',
      'import type { Config as Current } from "./types/generated/nextly-types.js";',
      'import type { GeneratedTypes } from "nextly";',
      'export const viaOld: Old["singles"] = {};',
      'export const viaCurrent: Current["singles"] = {};',
      'export const viaNextly: GeneratedTypes["collections"] = {};',
      "",
    ].join("\n")
  );
  await writeFile(
    join(cwd, "tsconfig.uses-both.json"),
    JSON.stringify({
      compilerOptions: {
        strict: true,
        skipLibCheck,
        types: [],
        module: "esnext",
        moduleResolution: "bundler",
        paths: { nextly: ["./nextly-stub.d.ts"] },
      },
      files: ["src/uses-both.ts"],
    })
  );
  return compile(["-p", "tsconfig.uses-both.json"], cwd).map(
    d => `${d.code}: ${d.message}`
  );
}

describe("a project that kept the re-export, importing both names after generation", () => {
  // A project on alpha.67 or alpha.68 has the re-export and may still import
  // payload-types. Nextly leaves the file as it is, so those imports keep
  // reading the types just generated, with one declaration of GeneratedTypes.
  it.each([false, true])(
    "type-checks with skipLibCheck %s, every name reading the current types",
    async skipLibCheck => {
      const cwd = await appWithDefaultPath();
      await mkdir(generatedDir(cwd), { recursive: true });
      await writeFile(join(generatedDir(cwd), "payload-types.ts"), SHIM);

      await runGenerateTypes(
        { cwd, quiet: true, zod: false },
        createContext({ quiet: true, cwd })
      );

      expect(await typeErrorsImportingBothNames(cwd, skipLibCheck)).toEqual([]);
    }
  );
});

describe("generate:types --help", () => {
  it("names the default types file", () => {
    const program = new Command();
    registerGenerateTypesCommand(program);
    const command = program.commands.find(c => c.name() === "generate:types");

    expect(command?.helpInformation()).toContain(
      DEFAULT_TYPESCRIPT_CONFIG.outputFile
    );
    expect(DEFAULT_TYPESCRIPT_CONFIG.outputFile).toMatch(/\/nextly-types\.ts$/);
  });
});
